func:
if (msg.payload === "conectado") {
    msg.payload = "ESP32 conectado";
    msg.ui_update = { color: "#16a34a" };
} else if (msg.payload === "desconectado") {
    msg.payload = "ESP32 desconectado";
    msg.ui_update = { color: "#dc2626" };
}
return msg;

const hora = new Date().toLocaleTimeString('es-CR', { hour12: false });
let txt = 'OK';
if (typeof msg.payload === 'string') {
  txt = msg.payload;
} else if (msg.payload && typeof msg.payload === 'object') {
  txt = msg.payload.msg || 'OK';
}
msg.payload = ${txt} ();
return msg;

let p = msg.payload;
if (!p) return null;
let now = Date.now();
let ang = typeof p.angulo === 'number' ? Number(p.angulo.toFixed(2)) : null;
let obj = null;
if (typeof p.setpoint === 'number') {
    obj = Number(p.setpoint.toFixed(2));
} else if (typeof p.anguloObjetivo === 'number') {
    obj = Number(p.anguloObjetivo.toFixed(2));
}

if (ang !== null) {
    node.send({ topic: "Ángulo Real (°)", payload: ang, timestamp: now });
}
if (obj !== null) {
    node.send({ topic: "Ángulo Objetivo (°)", payload: obj, timestamp: now });
}
return null;

let p = msg.payload;
if (!p) return null;
let now = Date.now();
let pwm = typeof p.pwm === 'number' ? p.pwm : 0;
return { topic: "PWM Motor", payload: pwm, timestamp: now };

let p = msg.payload;
if (!p || typeof p.angulo !== 'number') return null;

let now = Date.now();
let prev = context.get('prev');

if (!prev) {
    context.set('prev', { t: now, ang: p.angulo, pul: p.pulsos || 0 });
    return null;
}

let dt = (now - prev.t) / 1000.0;
if (dt <= 0.05 || dt > 2.0) dt = 0.5;

let dAng = p.angulo - prev.ang;
let dPul = (p.pulsos !== undefined ? p.pulsos : 0) - prev.pul;

let vel = dAng / dt;
let step = dPul;

context.set('prev', { t: now, ang: p.angulo, pul: p.pulsos || 0 });

node.send({ topic: "Ángulo (°)", payload: Number(p.angulo.toFixed(2)), timestamp: now });
node.send({ topic: "Velocidad (°/s)", payload: Number(vel.toFixed(2)), timestamp: now });
node.send({ topic: "Step (pulsos)", payload: step, timestamp: now });
return null;

let p = msg.payload;
if (!p || typeof p !== 'object') return null;

// Marcha (Manual / Auto)
let mMarcha = { payload: p.modoManual ? "⚠️ Manual" : "🟢 Automático" };

// Clasificador Activo
let mModo = { payload: p.metodoActivo ? p.metodoActivo.toUpperCase() : "-" };

// Posición Confiable
let mPosConf = { payload: p.posicionConfiable ? "✅ Confiable" : "❌ No Confiable" };

// Tabla NVS
let mTablaVal = { payload: p.tablaValida ? "✅ Calibrada" : "⚠️ Sin Calibrar" };

// Bloqueo
let mBloqueo = { payload: p.bloqueo ? ("🛑 Bloqueo (" + (p.razonCorte || "alerta") + ")") : "✅ Normal" };

// Fase de Marcha y Ciclo
let mFase = { payload: (p.fase || "-") + " (ciclo " + (p.ciclo || 0) + ")" };

// Verificación AS5600
let angV = typeof p.anguloVerificacion === 'number' ? p.anguloVerificacion.toFixed(1) + "°" : "-";
let disc = typeof p.discrepancia === 'number' ? p.discrepancia.toFixed(1) + "°" : "-";
let mAngVerif = { payload: angV + " (disc: " + disc + ")" };

// Pulsos
let mPulsos = { payload: (p.pulsos !== undefined ? p.pulsos : "-") };

// Control Motor (PWM y Error)
let errStr = typeof p.error === 'number' ? p.error.toFixed(1) + "°" : "-";
let mMotor = { payload: "PWM " + (p.pwm || 0) + " | Err " + errStr };

// Terreno y Clase
let terStr = typeof p.terreno === 'number' ? p.terreno.toFixed(1) + "°" : "-";
let mTerreno = { payload: terStr + " | " + (p.clase || "-") };

return [mMarcha, mModo, mPosConf, mTablaVal, mBloqueo, mFase, mAngVerif, mPulsos, mMotor, mTerreno];

const p = msg.payload || {};

function toNum(val, def = 0) {
    if (typeof val === 'number' && !isNaN(val)) return val;
    const n = Number(val);
    return isNaN(n) ? def : n;
}

function toBoolNum(val) {
    return (val === true || val === 1 || val === "true") ? 1 : 0;
}

const ang = toNum(p.angulo !== undefined ? p.angulo : p.anguloCalibrado);
const angVerif = toNum(p.anguloVerificacion !== undefined ? p.anguloVerificacion : p.anguloActual);
const piePlanoCalc = toBoolNum((p.contactoTalon && p.contactoPunta) || p.fase === "apoyo_plano" || p.piePlano);

const fields = {
    // Angulos y posicion
    angulo: ang,
    anguloCalibrado: ang,
    anguloVerificacion: angVerif,
    anguloActual: angVerif,
    discrepancia: toNum(p.discrepancia, -1),
    pulsos: toNum(p.pulsos),
    velAngular: toNum(p.velAngular),
    velPulsos: toNum(p.velPulsos),

    // Control y setpoint
    setpoint: toNum(p.setpoint !== undefined ? p.setpoint : p.anguloObjetivo),
    anguloObjetivo: toNum(p.anguloObjetivo),
    error: toNum(p.error),
    errSeguimiento: toNum(p.errSeguimiento),
    pwm: toNum(p.pwm),
    zonaMuerta: toNum(p.zonaMuerta),

    // Marcha y paso simulado
    pasoActivo: toBoolNum(p.pasoActivo),
    pctCiclo: toNum(p.pctCiclo, -1),
    offsetTerreno: toNum(p.offsetTerreno),
    msCiclo: toNum(p.msCiclo),
    amplitud: toNum(p.amplitud),

    // Tibia, terreno y apoyos
    anguloTibia: toNum(p.anguloTibia),
    moduloAcc: toNum(p.moduloAcc, 1.0),
    terreno: toNum(p.terreno),
    terrenoValido: toBoolNum(p.terrenoValido),
    contactoTalon: toBoolNum(p.contactoTalon),
    contactoPunta: toBoolNum(p.contactoPunta),
    piePlano: piePlanoCalc,

    // Estados del sistema
    posicionConfiable: toBoolNum(p.posicionConfiable),
    tablaValida: toBoolNum(p.tablaValida),
    bloqueo: toBoolNum(p.bloqueo),
    motorActivo: toBoolNum(p.motorActivo),
    ciclo: toNum(p.ciclo)
};

const tags = {
    metodoActivo: p.metodoActivo ? String(p.metodoActivo) : "desconocido",
    fase: p.fase ? String(p.fase) : "desconocida",
    subfase: p.subfase ? String(p.subfase) : "inactivo",
    clase: p.clase ? String(p.clase) : "plano"
};

msg.payload = [fields, tags];
msg.measurement = "telemetria";
return msg;

const p = msg.payload || {};
const esValido = (p.terrenoValido === true || p.terrenoValido === 1 || p.terrenoValido === "true");

if (esValido && typeof p.terreno !== 'undefined') {
    return {
        payload: p.terreno,
        ui_update: {
            segments: [
                { from: -40, color: "#5CD65C" },
                { from: -15, color: "#FFC800" },
                { from: 15, color: "#EA5353" }
            ]
        }
    };
} else {
    // Terreno inválido: gauge atenuado en gris
    return {
        payload: typeof p.terreno !== 'undefined' ? p.terreno : 0,
        ui_update: {
            segments: [
                { from: -40, color: "#9ca3af" }
            ]
        }
    };
}

let buffer = context.get('buffer') || [];

if (msg.payload === '__CLEAR__') {
    buffer = [];
    context.set('buffer', buffer);
    return { payload: "" };
}

let texto = typeof msg.payload === 'string' ? msg.payload.trimEnd() : String(msg.payload);
if (texto.length === 0) return null;

let hora = new Date().toLocaleTimeString('es-CR', { hour12: false });
let linea = `[${hora}] ${texto}`;

buffer.push(linea);
if (buffer.length > 70) {
    buffer.shift();
}
context.set('buffer', buffer);

msg.payload = buffer.join("\n");
return msg;

let val = parseInt(msg.payload, 10);
if (!isNaN(val)) {
    return { topic: 'tobillo/comando', payload: 'ciclo:' + val };
}
return null;

let val = parseFloat(msg.payload);
if (!isNaN(val)) {
    return { topic: 'tobillo/comando', payload: 'amplitud:' + val.toFixed(2) };
}
return null;

let ter = flow.get('terreno_paso');
if (typeof ter !== 'number') ter = 0;
return { topic: 'tobillo/comando', payload: 'paso:' + ter.toFixed(1) };

let ter = flow.get('terreno_paso');
if (typeof ter !== 'number') ter = 0;
let t = ter.toFixed(1);
return { topic: 'tobillo/comando', payload: 'caminar:' + t + ',' + t + ',' + t + ',' + t + ',' + t };

let p = msg.payload;
if (!p) return null;

let pasoActivo = !!p.pasoActivo;
let subfase = p.subfase || (pasoActivo ? "ACTIVO" : "REPOSO");
let pct = typeof p.pctCiclo === 'number' ? p.pctCiclo.toFixed(1) + "%" : "--";
let err = typeof p.errSeguimiento === 'number' ? p.errSeguimiento.toFixed(2) + "°" : "--";
let estadoHtml = pasoActivo ? '<span style="color:#16a34a;font-weight:bold;">EN MARCHA</span>' : '<span style="color:#64748b;">DETENIDO</span>';

return [
    { payload: estadoHtml },
    { payload: subfase },
    { payload: pct },
    { payload: err }
];
